<?php
declare(strict_types=1);
namespace app\services\growth;
use think\facade\Db;
use mohe\exceptions\AdminException;

/** 档案只汇集同一员工的正式来源，积分与业务分数分别展示，不维护人工汇总总分。 */
final class GrowthProfileServices
{
    /** 历史人员选择只带姓名与状态，不把原门店成长资料迁到新门店。 */
    public function people(array $c): array
    {
        $current=app()->make(GrowthAccessServices::class)->employees($c);$q=Db::name('growth_task');app()->make(GrowthAccessServices::class)->taskScope($q,$c);$past=array_map('intval',$q->distinct(true)->column('employee_id'));$ids=array_values(array_unique(array_merge($current,$past)));$rows=Db::name('employee')->whereIn('id',$ids)->field('id,name,status,is_del')->order('id')->select()->toArray();foreach($rows as &$r)$r['historical_only']=!in_array((int)$r['id'],$current,true);return $rows;
    }
    /** 完整档案按来源分别分页，不能用最近100条摘要冒充全部历史。 */
    public function history(array $c,int $employee,array $in): array
    {
        if(!$c['manager']&&$employee!==$c['employee_id'])throw new AdminException('只能查看本人成长档案');if(!Db::name('employee')->where('id',$employee)->find())throw new AdminException('员工不存在');if(!$c['super']&&$employee!==$c['employee_id']&&!in_array($employee,app()->make(GrowthAccessServices::class)->employees($c),true)){$visible=Db::name('growth_task')->where('employee_id',$employee);app()->make(GrowthAccessServices::class)->taskScope($visible,$c);if(!$visible->find())throw new AdminException('员工不在当前历史数据范围');}
        $types=['tasks'=>'学习与活动任务','attempts'=>'正式练考结果','evaluations'=>'实操鉴定','coaching'=>'带教记录','points'=>'积分流水','certificates'=>'证书记录','jobs'=>'任职历史','organizations'=>'组织归属历史'];$kind=(string)($in['kind']??'tasks');if(!isset($types[$kind]))throw new AdminException('成长历史类型无效');$a=app()->make(GrowthAccessServices::class);$fields='r.*';$id='r.id';
        if($kind==='tasks'){$q=Db::name('growth_task')->alias('r')->where('r.employee_id',$employee);$a->taskScope($q,$c,'r');$fields='r.id,r.title,r.kind,r.state,r.conclusion,r.assigned_at,r.source_id,r.source_type,r.employee_id';}
        elseif(in_array($kind,['points','certificates'],true)){$q=$a->rewardQuery($c,$kind==='points'?'growth_point_ledger':'growth_certificate',$employee);$fields='r.*,t.id AS linked_task_id';if($kind==='points'&&!empty($in['rule_id']))$q->where('r.rule_id',(int)$in['rule_id']);}
        elseif(in_array($kind,['attempts','evaluations','coaching'],true)){$tables=['attempts'=>'growth_attempt','evaluations'=>'growth_evaluation','coaching'=>'growth_coaching'];$q=Db::name($tables[$kind])->alias('r')->join('growth_task t','t.id=r.task_id')->where('r.employee_id',$employee);$a->taskScope($q,$c,'t');if($kind==='attempts')$q->where('r.state','PUBLISHED');$fields='r.*,t.title AS task_title';}
        elseif($kind==='jobs'){$q=Db::name('staff_job_position')->alias('r')->leftJoin('position p','p.id=r.position_id')->leftJoin('system_store s','s.id=r.store_id')->where('r.employee_id',$employee);if(!$c['super']&&$employee!==$c['employee_id'])$q->whereIn('r.store_id',(array)$c['store_ids']);$fields='r.id,r.store_id,r.position_id,p.name AS position_name,s.name AS store_name,r.status,r.is_del,r.start_time,r.end_time,r.reason';}
        else{$q=Db::name('organization_employee')->alias('r')->join('organization o','o.id=r.org_id')->where('r.employee_id',$employee);if(!$c['super']&&$employee!==$c['employee_id'])$q->whereIn('r.org_id',$c['organization_ids']);$fields='r.id,r.org_id,o.name AS organization_name,r.status,r.is_del,r.add_time';}
        [$rows,$page]=GrowthPage::take($q->field($fields),$in['page']??1,$id);foreach($rows as &$r){$r['task_id']=(int)($r['task_id']??($kind==='tasks'?$r['id']:0));$r['source_id']=(int)($r['source_id']??$r['id']);
            if($kind==='tasks'){$r['occurred_at']=(int)$r['assigned_at'];$labels=['NOT_STARTED'=>'未开始','IN_PROGRESS'=>'进行中','PENDING'=>'待确认','COMPLETED'=>'已完成','PAUSED'=>'已暂停','CANCELLED'=>'已作废','RETURNED'=>'待补充','PASSED'=>'通过','FAILED'=>'未通过','UNTESTED'=>'未检验','QUALIFIED'=>'已达标'];$r['summary']=($labels[$r['state']]??$r['state']).' · '.($labels[$r['conclusion']]??$r['conclusion']);}
            elseif($kind==='points'){$r['title']=$r['reason'];$r['summary']=((int)$r['delta']>0?'+':'').$r['delta'].' 成长积分';$proof=GrowthCommandServices::decode($r['evidence_json']);$r['task_id']=(int)($proof['task_id']??$r['linked_task_id']??0);}
            elseif($kind==='certificates'){$r['occurred_at']=(int)$r['issued_at'];$r['summary']=$r['certificate_number'].' · '.(['VALID'=>'有效','EXPIRED'=>'已到期','REVOKED'=>'已撤销'][$r['state']]??$r['state']);$r['evidence']=GrowthCommandServices::decode($r['evidence_json']);$r['history']=Db::name('growth_certificate_action')->where('certificate_id',$r['id'])->order('id','desc')->select()->toArray();}
            elseif($kind==='jobs'){$r['title']=$r['position_name']?:'原岗位';$r['occurred_at']=(int)$r['start_time'];$r['summary']=($r['store_name']?:'原门店').' · '.($r['end_time']||!$r['status']?'历史任职':'当前任职').' · '.$r['reason'];}
            elseif($kind==='organizations'){$r['title']=$r['organization_name'];$r['occurred_at']=(int)$r['add_time'];$r['summary']=$r['status']&&!$r['is_del']?'有效组织归属':'历史组织归属';}
            elseif($kind==='attempts'){$adjust=Db::name('growth_grade_adjustment')->where('attempt_id',$r['id'])->order('id','desc')->find();$r['score']=$adjust['score']??$r['score'];$r['passed']=$adjust['passed']??$r['passed'];$r['title']=$r['task_title'];$r['occurred_at']=(int)$r['published_at'];$r['summary']='第'.$r['attempt_no'].'次 · '.$r['score'].' / '.$r['max_score'].'分 · '.($r['passed']?'通过':'未通过');unset($r['questions_json'],$r['draft_answers_json'],$r['final_answers_json'],$r['answer_session_key']);}
            else{$r['title']=$r['task_title'];$r['summary']=$kind==='coaching'?(string)(GrowthCommandServices::decode($r['snapshot_json'])['body']??'已记录带教'):($r['conclusion']==='QUALIFIED'?'已达标':'需补练');}
        }return ['kind'=>$kind,'types'=>$types,'rows'=>$rows]+$page;
    }
    /** 汇集授权内正式来源；历史范围与本人全量积分等级分别处理。 */
    public function read(array $c,int $employee): array
    {
        if(!$c['manager']&&$employee!==$c['employee_id'])throw new AdminException('只能查看本人成长档案');if(!$c['super']&&!in_array($employee,app()->make(GrowthAccessServices::class)->employees($c),true)){$visible=Db::name('growth_task')->where('employee_id',$employee);app()->make(GrowthAccessServices::class)->taskScope($visible,$c);if(!$visible->find())throw new AdminException('员工不在当前历史数据范围');}
        $person=Db::name('employee')->where('id',$employee)->field('id,name,phone,status,is_del')->find();if(!$person)throw new AdminException('员工不存在');
        if(!$c['super']&&$employee!==$c['employee_id']&&!in_array($employee,app()->make(GrowthAccessServices::class)->employees($c),true))unset($person['phone']);
        $rewards=app()->make(GrowthRewardServices::class);
        $scope=Db::name('growth_task')->where('employee_id',$employee);app()->make(GrowthAccessServices::class)->taskScope($scope,$c);$taskIds=array_map('intval',(clone $scope)->column('id'));
        $tasks=$scope->order('id','desc')->limit(100)->field('id,title,kind,state,conclusion,assigned_at,completed_at,result_type,result_id,store_id,organization_id')->select()->toArray();
        $attempts=Db::name('growth_attempt')->where('employee_id',$employee)->whereIn('task_id',$taskIds)->where('state','PUBLISHED')->order('id','desc')->limit(100)->field('id,task_id,attempt_no,score,max_score,passed,published_at')->select()->toArray();foreach($attempts as &$a){$change=Db::name('growth_grade_adjustment')->where('attempt_id',$a['id'])->order('id','desc')->find();if($change){$a['score']=$change['score'];$a['passed']=$change['passed'];$a['adjustment_id']=$change['id'];}}
        $evaluations=Db::name('growth_evaluation')->where('employee_id',$employee)->whereIn('task_id',$taskIds)->order('id','desc')->limit(100)->field('id,task_id,capability_id,conclusion,score,evaluator_employee_id,occurred_at,valid_until,previous_evaluation_id')->select()->toArray();
        $jobQuery=Db::name('staff_job_position')->alias('j')->join('position p','p.id=j.position_id')->where('j.employee_id',$employee)->where('j.status',1)->where('j.is_del',0)->where('j.end_time',0);if(!$c['super']&&$employee!==$c['employee_id'])$jobQuery->whereIn('j.store_id',(array)$c['store_ids']);$jobs=$jobQuery->field('j.id,j.position_id,j.store_id,p.name AS position_name')->select()->toArray();
        $positions=array_map('intval',array_column($jobs,'position_id'));$capabilities=$positions?Db::name('growth_capability')->whereIn('position_id',$positions)->select()->toArray():[];
        foreach($capabilities as &$cap){$result=Db::name('growth_evaluation')->where('employee_id',$employee)->whereIn('task_id',$taskIds)->where('capability_id',$cap['id'])->order('id','desc')->find();$cap['conclusion']=$result&&(!$result['valid_until']||$result['valid_until']>time())?$result['conclusion']:'NOT_EVALUATED';$cap['evaluation_id']=$result['id']??null;}
        $history=Db::name('staff_job_position')->alias('j')->leftJoin('position p','p.id=j.position_id')->where('j.employee_id',$employee);if(!$c['super']&&$employee!==$c['employee_id'])$history->whereIn('j.store_id',(array)$c['store_ids']);$personnel=$history->field('j.id,j.store_id,j.position_id,p.name AS position_name,j.start_time,j.end_time,j.status,j.reason,j.operator_name')->order('j.id','desc')->limit(100)->select()->toArray();
        $appraisals=Db::name('growth_appraisal')->alias('a')->join('growth_task t',"t.source_type='appraisal' AND t.source_id=a.id")->where('a.employee_id',$employee)->where('a.state','PUBLISHED');app()->make(GrowthAccessServices::class)->taskScope($appraisals,$c,'t');$appraisalRows=$appraisals->field('a.*')->order('a.id','desc')->limit(100)->select()->toArray();foreach($appraisalRows as &$row)$row['result']=Db::name('growth_appraisal_result')->where('appraisal_id',$row['id'])->order('id','desc')->find();
        $visiblePoints=app()->make(GrowthAccessServices::class)->rewardQuery($c,'growth_point_ledger',$employee);$pointBalance=($c['super']||$employee===$c['employee_id'])?$rewards->balance($employee):(int)(clone $visiblePoints)->sum('r.delta');$levelHistory=Db::name('growth_level_event')->where('employee_id',$employee);if(!$c['super']&&$employee!==$c['employee_id'])$levelHistory->whereRaw('1=0');
        $orgHistory=Db::name('organization_employee')->alias('oe')->join('organization o','o.id=oe.org_id')->where('oe.employee_id',$employee);if(!$c['super']&&$employee!==$c['employee_id'])$orgHistory->whereIn('oe.org_id',$c['organization_ids']);$organizationHistory=$orgHistory->field('oe.id,oe.org_id,o.name AS organization_name,oe.status,oe.is_del,oe.add_time')->order('oe.id','desc')->limit(100)->select()->toArray();
        $certificates=app()->make(GrowthAccessServices::class)->rewardQuery($c,'growth_certificate',$employee)->field('r.*')->order('r.id','desc')->limit(100)->select()->toArray();foreach($certificates as &$cert){$cert['evidence']=GrowthCommandServices::decode($cert['evidence_json']);$cert['history']=Db::name('growth_certificate_action')->where('certificate_id',$cert['id'])->order('id','desc')->select()->toArray();}
        return ['organization_history'=>$organizationHistory,'history_limit'=>100,'point_scope_note'=>($c['super']||$employee===$c['employee_id'])?'员工全部有效积分':'仅当前授权范围内积分，等级需本人或全量权限查看','personnel_history'=>$personnel,'appraisals'=>$appraisalRows,'level_history'=>$levelHistory->order('id','desc')->limit(50)->select()->toArray(),'task_history'=>Db::name('growth_task_action')->whereIn('task_id',$taskIds)->field('id,task_id,action,reason,actor_key,created_at')->order('id','desc')->limit(100)->select()->toArray(),'employee'=>$person,'jobs'=>$jobs,'capabilities'=>$capabilities,'tasks'=>$tasks,'attempts'=>$attempts,'evaluations'=>$evaluations,'point_balance'=>$pointBalance,'level'=>($c['super']||$employee===$c['employee_id'])?$rewards->level($employee):null,'point_ledger'=>app()->make(GrowthAccessServices::class)->rewardQuery($c,'growth_point_ledger',$employee)->field('r.*')->order('r.id','desc')->limit(100)->select()->toArray(),'certificates'=>$certificates,'coaching'=>Db::name('growth_coaching')->where('employee_id',$employee)->whereIn('task_id',$taskIds)->order('id','desc')->limit(100)->select()->toArray(),'data_as_of'=>time()];
    }
}
